<?php
require_once '../includes/config.php'; require_role('admin'); $pdo=db();
$labels=['manage_site'=>'Manage Site customization','products'=>'Product catalog access','inventory'=>'Inventory management','orders'=>'Order management','support'=>'Customer support','manage_staff'=>'Create/manage staff accounts'];
if($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $action=$_POST['action']??'';
 if($action==='add') { $name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??''); if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){flash('danger','Enter a valid name/email and a password of at least 8 characters.');redirect('staff.php');} try{$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO users(name,email,password,role,status) VALUES(?,?,?,'staff',1)");$st->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$perms=array_intersect(array_keys($labels),$_POST['permissions']??[]);$ins=$pdo->prepare('INSERT INTO staff_permissions(user_id,permission_key,allowed) VALUES(?,?,1)');foreach($perms as $perm)$ins->execute([$id,$perm]);$pdo->commit();flash('success','Staff account created with selected permissions.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Could not create staff account; check that the email is unique.');}}
 elseif($action==='permissions'){ $id=(int)($_POST['id']??0);$chk=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='staff'");$chk->execute([$id]);if($chk->fetchColumn()){ $pdo->beginTransaction();$pdo->prepare('DELETE FROM staff_permissions WHERE user_id=?')->execute([$id]);$ins=$pdo->prepare('INSERT INTO staff_permissions(user_id,permission_key,allowed) VALUES(?,?,1)');foreach(array_intersect(array_keys($labels),$_POST['permissions']??[]) as $perm)$ins->execute([$id,$perm]);$pdo->commit();flash('success','Staff permissions updated.');}}
 elseif($action==='toggle'){$pdo->prepare('UPDATE users SET status=1-status WHERE id=? AND role="staff"')->execute([(int)$_POST['id']]);flash('success','Staff status updated.');}
 elseif($action==='delete'){$pdo->prepare('DELETE FROM users WHERE id=? AND role="staff"')->execute([(int)$_POST['id']]);flash('success','Staff account deleted.');}
 redirect('staff.php'); }
$rows=$pdo->query("SELECT id,name,email,status,created_at FROM users WHERE role='staff' ORDER BY id DESC")->fetchAll();$permStmt=$pdo->prepare('SELECT permission_key FROM staff_permissions WHERE user_id=? AND allowed=1');$title='Staff & Permissions';require '../includes/header.php';
?>
<div class="d-flex justify-content-between align-items-center flex-wrap gap-3"><div><h1 class="section-title mb-1">Staff & Permissions</h1><p class="text-secondary mb-0">Grant only the sections each staff member needs.</p></div><button class="btn btn-purple" data-bs-toggle="modal" data-bs-target="#addStaff"><i class="bi bi-person-plus me-1"></i>Add Staff</button></div>
<div class="alert alert-info mt-3"><i class="bi bi-shield-check me-2"></i>Permissions are checked on the server. Only admins can grant or revoke permissions and manage staff accounts.</div>
<div class="row g-3 mt-1"><?php foreach($rows as $r): $permStmt->execute([$r['id']]);$activePerms=$permStmt->fetchAll(PDO::FETCH_COLUMN); ?><div class="col-12"><div class="bg-white border rounded-4 p-3 p-lg-4"><div class="d-flex justify-content-between align-items-start flex-wrap gap-2"><div><h5 class="mb-1"><?=e($r['name'])?></h5><div class="text-secondary small"><?=e($r['email'])?> · Joined <?=e(date('d M Y',strtotime($r['created_at'])))?></div></div><span class="badge <?=$r['status']?'text-bg-success':'text-bg-secondary'?>"><?=$r['status']?'Active':'Inactive'?></span></div><form method="post" class="mt-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="permissions"><label class="form-check mb-2"><input class="form-check-input select-all-permissions" type="checkbox"> <span class="form-check-label fw-semibold">All available permissions</span></label><div class="row g-2"><?php foreach($labels as $key=>$label): ?><div class="col-sm-6 col-lg-4"><label class="border rounded-3 p-2 d-flex align-items-center gap-2 h-100"><input class="form-check-input mt-0" type="checkbox" name="permissions[]" value="<?=e($key)?>" <?=in_array($key,$activePerms,true)?'checked':''?>><span><?=e($label)?></span></label></div><?php endforeach; ?></div><div class="d-flex gap-2 mt-3 flex-wrap"><button class="btn btn-sm btn-purple">Save permissions</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="toggle" class="btn btn-sm btn-outline-secondary"><?=$r['status']?'Deactivate':'Activate'?></button></form><form method="post" onsubmit="return confirm('Permanently delete this staff account?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="delete" class="btn btn-sm btn-outline-danger">Delete</button></form></div></div></div><?php endforeach; ?></div>
<div class="modal fade" id="addStaff" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="modal-header"><h5 class="modal-title">Create staff account</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name</label><input name="name" class="form-control" required maxlength="120"></div><div class="col-md-6"><label class="form-label">Email</label><input name="email" type="email" class="form-control" required maxlength="190"></div><div class="col-12"><label class="form-label">Temporary password (minimum 8 characters)</label><input name="password" type="password" class="form-control" minlength="8" required autocomplete="new-password"></div></div><hr><strong>Permissions</strong><p class="small text-secondary">Choose the sections this staff account can access.</p><label class="form-check mb-2"><input class="form-check-input select-all-permissions" type="checkbox"> <span class="form-check-label fw-semibold">All available permissions</span></label><div class="row g-2"><?php foreach($labels as $key=>$label): ?><div class="col-sm-6"><label class="border rounded-3 p-2 d-flex align-items-center gap-2"><input class="form-check-input mt-0" type="checkbox" name="permissions[]" value="<?=e($key)?>"><span><?=e($label)?></span></label></div><?php endforeach; ?></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-purple">Create staff</button></div></form></div></div></div>
<script>document.querySelectorAll('.select-all-permissions').forEach(master=>master.addEventListener('change',()=>{const form=master.closest('form');if(form)form.querySelectorAll('input[name="permissions[]"]').forEach(box=>box.checked=master.checked);}));document.querySelectorAll('input[name="permissions[]"]').forEach(box=>box.addEventListener('change',()=>{const form=box.closest('form');const master=form?.querySelector('.select-all-permissions');if(master)master.checked=[...form.querySelectorAll('input[name="permissions[]"]')].every(x=>x.checked);}));</script><?php require '../includes/footer.php'; ?>